const body = $json.body || {};

const chatLogId = Number(body.chat_log_id);

const feedback = String(
  body.feedback || ''
).trim();

if (
  !Number.isInteger(chatLogId) ||
  chatLogId <= 0
) {
  throw new Error(
    'chat_log_id must be a positive integer.'
  );
}

if (
  !['useful', 'not_useful'].includes(feedback)
) {
  throw new Error(
    'Feedback must be either "useful" or "not_useful".'
  );
}

return {
  json: {
    chat_log_id: chatLogId,
    feedback
  }
};

const status = String(
  $json.status || 'error'
).trim();

const chatLogId = Number(
  $json.chat_log_id
);

if (status === 'not_found') {
  return {
    json: {
      status: 'not_found',
      message: 'Chat log not found.',
      chat_log_id:
        Number.isInteger(chatLogId)
          ? chatLogId
          : null
    }
  };
}

if (status !== 'success') {
  throw new Error(
    'Unexpected feedback save result.'
  );
}

if (
  !Number.isInteger(chatLogId) ||
  chatLogId <= 0
) {
  throw new Error(
    'Saved chat_log_id is missing or invalid.'
  );
}

const feedback = String(
  $json.feedback || ''
).trim();

if (
  !['useful', 'not_useful'].includes(feedback)
) {
  throw new Error(
    'Saved feedback value is invalid.'
  );
}

return {
  json: {
    status: 'success',
    message: 'Feedback saved successfully.',
    feedback,
    chat_log_id: chatLogId
  }
};
